#!/usr/bin/env python3
"""Round-2 watermark protocol on the re-exported line-numbered PDF.
Three layers: text layer scan, metadata scan, pixel-level corner render."""
import subprocess, re, sys

PDF = sys.argv[1] if len(sys.argv) > 1 else "paper/latex/main.pdf"
fails = []

# 1. text layer: AI-generation markers in any language
txt = subprocess.run(["pdftotext", PDF, "-"], capture_output=True, text=True).stdout
markers = ["AI生成", "AI 生成", "AIGC", "由AI", "AI content",
           "AI写作", "智能生成", "AI-watermark"]
# note: "AI-generated"/"Generated by" excluded: the manuscript legitimately
# uses "generated by" for reference generation; the round-2 watermark marker
# was the viewer-injected "AI生成" badge, absent from the text layer.
hits = [m for m in markers if m.lower() in txt.lower()]
print(f"[1] text layer: {'CLEAN' if not hits else 'HITS: ' + repr(hits)}")
if hits: fails.append("text")

# 2. metadata
info = subprocess.run(["pdfinfo", PDF], capture_output=True, text=True).stdout
bad_meta = [l for l in info.splitlines() if re.search(r"(?i)ai|generat|watermark", l) and "Creator" not in l and "Producer" not in l]
print(f"[2] metadata : {'CLEAN' if not bad_meta else bad_meta}")
print("    Creator/Producer:", [l for l in info.splitlines() if l.startswith(("Creator", "Producer"))])
if bad_meta: fails.append("meta")

# 3. pixel corner: render p77 + p1 at 150 dpi, check bottom-right 300x220 px for non-white
import glob, os
for page in ("77", "1"):
    subprocess.run(["pdftoppm", "-f", page, "-l", page, "-r", "150", "-png", PDF, f"/tmp/wm{page}"], check=True)
    fn = glob.glob(f"/tmp/wm{page}-*.png")[0]
    from PIL import Image
    im = Image.open(fn).convert("L")
    W, H = im.size
    crop = im.crop((W - 300, H - 220, W, H))
    px = list(crop.getdata())
    nonwhite = sum(1 for v in px if v < 240)
    print(f"[3] p{page} bottom-right 300x220: {nonwhite} non-white px of {len(px)}", "(page number/footer only expected)")
    if page == "77" and nonwhite > 30: fails.append(f"p77 corner {nonwhite}")

print("VERDICT:", "FAIL " + str(fails) if fails else "ALL CLEAN")
sys.exit(1 if fails else 0)
